#include <bits/stdc++.h>
using namespace std;

#define RANG(i,st,ed) for(int i=st;i<=ed;++i)
#define RANG_REV(i,st,ed) for(int i=st;i>=ed;--i)
typedef long long LL;

inline int readInt() {
    int x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-'){f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

inline LL readLong() {
    LL x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-'){f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

const int MAXN=32,MOD=1000000007;

inline void addMod(int &x,int y){
    x+=y;
    if(x>=MOD) x-=MOD;
}

struct Mat {
    int mat[MAXN][MAXN];
    void init() {
        memset(mat,0,sizeof(mat));
    }
    void printMat() {
        for(int i=1;i<=n+1;++i){
            for(int j=1;j<=n+1;++j){
                printf("%d%c",mat[i][j],j==n+1?'\n':' ');
            }
        }
        putchar('\n');
    }
    Mat operator*(const Mat &rhs) const {
        Mat res; res.init();
        for(int i=1;i<=n+1;++i)
            for(int j=1;j<=n+1;++j)
                for(int k=1;k<=n+1;++k)
                    addMod(res.mat[i][j],(long long)mat[i][k]*rhs.mat[k][j]%MOD);
        return res;
    }
};

int n;
Mat base, A[MAXN], pre[MAXN], suf[MAXN], ans;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    ll m=readLong(); n=readInt();
    base.init();
    for(int i=1;i<=n;++i) base.mat[i][i]=1;
    ans=base;
    for(int i=1;i<=n;++i){
        A[i]=base;
        A[i].mat[i][i]=1;
    }
    pre[0]=base; suf[n+1]=base;
    for(;m; m/=n){
        LL u=m%n;
        if(u){
            LL s=0;
            for(LL v=m;v;v/=n) s=(s+v/n)%n;
            u=(s+u-1)%n+1;
            for(;u!=s;--u){
                if(u<=0) u+=n;
                ans=A[u]*ans;
            }
        }
        for(int i=1;i<=n;++i) pre[i]=pre[i-1]*A[i];
        for(int i=n;i>=1;--i) suf[i]=A[i]*suf[i+1];
        for(int i=1;i<=n;++i) A[i]=suf[i]*pre[i-1];
    }
    int total=1;
    for(int i=1;i<=n;++i) addMod(total,ans.mat[n+1][i]);
    printf("%d\n",total);
    return 0;
}
